import { createRoute, z } from '@hono/zod-openapi'

const UserTypeStringSchema = z.enum(['User', 'Organization', 'Bot']).openapi('UserTypeString')

const VisibilityStringSchema = z.enum(['public', 'limited', 'private']).openapi('VisibilityString')

