export const getAdminActionsJobsRoute = createRoute({
  method: 'get',
  path: '/admin/actions/jobs',
  tags: ['admin'],
  summary: 'Lists all jobs',
  operationId: 'listAdminWorkflowJobs',
  request: {
    query: z.object({
      status: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'workflow status (requested, pending, queued, in_progress, failure, success, skipped)',
            in: 'query',
            name: 'status',
            schema: { type: 'string' },
            required: false,
          },
        }),
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'page number of results to return (1-based)',
            in: 'query',
            name: 'page',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'page size of results',
            in: 'query',
            name: 'limit',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      sort: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'sort jobs by attribute. Supported values are "id". Default is "id"',
            in: 'query',
            name: 'sort',
            schema: { type: 'string' },
            required: false,
          },
        }),
      order: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'sort order, either "asc" (ascending) or "desc" (descending). Default is "asc"',
            in: 'query',
            name: 'order',
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: { 200: WorkflowJobsListResponse, default: ErrorResponse },
})

