export const deleteAdminUsersUsernameKeysIdRoute = createRoute({
  method: 'delete',
  path: '/admin/users/{username}/keys/{id}',
  tags: ['admin'],
  summary: "Delete a user's public key",
  operationId: 'adminDeleteUserPublicKey',
  request: {
    params: z.object({
      username: z
        .string()
        .openapi({
          param: {
            description: 'username of the user whose public key is to be deleted',
            in: 'path',
            name: 'username',
            required: true,
            schema: { type: 'string' },
          },
        }),
      id: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            description: 'id of the key to delete',
            in: 'path',
            name: 'id',
            required: true,
            schema: { format: 'int64', type: 'integer' },
          },
        }),
    }),
  },
  responses: { 204: EmptyResponse, default: ErrorResponse },
})

