export const getNotificationsRoute = createRoute({
  method: 'get',
  path: '/notifications',
  tags: ['notification'],
  summary: "List users's notification threads",
  operationId: 'notifyGetList',
  request: {
    query: z.object({
      all: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description: 'If true, show notifications marked as read. Default value is false',
            in: 'query',
            name: 'all',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
      'status-types': z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'Show notifications with the provided status types. Options are: unread, read and/or pinned. Defaults to unread & pinned.',
            explode: true,
            in: 'query',
            name: 'status-types',
            schema: { items: { type: 'string' }, type: 'array' },
            style: 'form',
            required: false,
          },
        }),
      'subject-type': z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.enum(['issue', 'pull', 'commit', 'repository'])),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'filter notifications by subject type',
            explode: true,
            in: 'query',
            name: 'subject-type',
            schema: {
              items: { enum: ['issue', 'pull', 'commit', 'repository'], type: 'string' },
              type: 'array',
            },
            style: 'form',
            required: false,
          },
        }),
      since: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            description:
              'Only show notifications updated after the given time. This is a timestamp in RFC 3339 format',
            in: 'query',
            name: 'since',
            schema: { format: 'date-time', type: 'string' },
            required: false,
          },
        }),
      before: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            description:
              'Only show notifications updated before the given time. This is a timestamp in RFC 3339 format',
            in: 'query',
            name: 'before',
            schema: { format: 'date-time', type: 'string' },
            required: false,
          },
        }),
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'page number of results to return (1-based)',
            in: 'query',
            name: 'page',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'page size of results',
            in: 'query',
            name: 'limit',
            schema: { type: 'integer' },
            required: false,
          },
        }),
    }),
  },
  responses: { 200: NotificationThreadListResponse },
})

