export const getReposIssuesSearchRoute = createRoute({
  method: 'get',
  path: '/repos/issues/search',
  tags: ['issue'],
  summary: 'Search for issues across the repositories that the user has access to',
  operationId: 'issueSearchIssues',
  request: {
    query: z.object({
      state: z
        .enum(['open', 'closed', 'all'])
        .default('open')
        .exactOptional()
        .openapi({
          param: {
            description: 'State of the issue',
            in: 'query',
            name: 'state',
            schema: { default: 'open', enum: ['open', 'closed', 'all'], type: 'string' },
            required: false,
          },
        }),
      labels: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Comma-separated list of label names. Fetch only issues that have any of these labels. Non existent labels are discarded.',
            in: 'query',
            name: 'labels',
            schema: { type: 'string' },
            required: false,
          },
        }),
      milestones: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Comma-separated list of milestone names. Fetch only issues that have any of these milestones. Non existent milestones are discarded.',
            in: 'query',
            name: 'milestones',
            schema: { type: 'string' },
            required: false,
          },
        }),
      q: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Search string',
            in: 'query',
            name: 'q',
            schema: { type: 'string' },
            required: false,
          },
        }),
      type: z
        .enum(['issues', 'pulls'])
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter by issue type',
            in: 'query',
            name: 'type',
            schema: { enum: ['issues', 'pulls'], type: 'string' },
            required: false,
          },
        }),
      since: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            description: 'Only show issues updated after the given time (RFC 3339 format)',
            in: 'query',
            name: 'since',
            schema: { format: 'date-time', type: 'string' },
            required: false,
          },
        }),
      before: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            description: 'Only show issues updated before the given time (RFC 3339 format)',
            in: 'query',
            name: 'before',
            schema: { format: 'date-time', type: 'string' },
            required: false,
          },
        }),
      assigned: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter issues or pulls assigned to the authenticated user',
            in: 'query',
            name: 'assigned',
            schema: { default: false, type: 'boolean' },
            required: false,
          },
        }),
      created: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter issues or pulls created by the authenticated user',
            in: 'query',
            name: 'created',
            schema: { default: false, type: 'boolean' },
            required: false,
          },
        }),
      mentioned: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter issues or pulls mentioning the authenticated user',
            in: 'query',
            name: 'mentioned',
            schema: { default: false, type: 'boolean' },
            required: false,
          },
        }),
      review_requested: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            description: "Filter pull requests where the authenticated user's review was requested",
            in: 'query',
            name: 'review_requested',
            schema: { default: false, type: 'boolean' },
            required: false,
          },
        }),
      reviewed: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter pull requests reviewed by the authenticated user',
            in: 'query',
            name: 'reviewed',
            schema: { default: false, type: 'boolean' },
            required: false,
          },
        }),
      owner: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter by repository owner',
            in: 'query',
            name: 'owner',
            schema: { type: 'string' },
            required: false,
          },
        }),
      created_by: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Only show items which were created by the given user',
            in: 'query',
            name: 'created_by',
            schema: { type: 'string' },
            required: false,
          },
        }),
      team: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter by team (requires organization owner parameter)',
            in: 'query',
            name: 'team',
            schema: { type: 'string' },
            required: false,
          },
        }),
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            description: 'Page number of results to return (1-based)',
            in: 'query',
            name: 'page',
            schema: { default: 1, minimum: 1, type: 'integer' },
            required: false,
          },
        }),
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(0),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Number of items per page',
            in: 'query',
            name: 'limit',
            schema: { minimum: 0, type: 'integer' },
            required: false,
          },
        }),
    }),
  },
  responses: { 200: IssueListResponse, default: ErrorResponse },
})

