export const getReposOwnerRepoBranchesRoute = createRoute({
  method: 'get',
  path: '/repos/{owner}/{repo}/branches',
  tags: ['repository'],
  summary: "List a repository's branches",
  operationId: 'repoListBranches',
  request: {
    params: z.object({
      owner: z
        .string()
        .openapi({
          param: {
            description: 'owner of the repo',
            in: 'path',
            name: 'owner',
            required: true,
            schema: { type: 'string' },
          },
        }),
      repo: z
        .string()
        .openapi({
          param: {
            description: 'name of the repo',
            in: 'path',
            name: 'repo',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'page number of results to return (1-based)',
            in: 'query',
            name: 'page',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'page size of results',
            in: 'query',
            name: 'limit',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      q: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'branch name substring to filter by',
            in: 'query',
            name: 'q',
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: { 200: BranchListResponse },
})

