export const getReposOwnerRepoCommitsRoute = createRoute({
  method: 'get',
  path: '/repos/{owner}/{repo}/commits',
  tags: ['repository'],
  summary: 'Get a list of all commits from a repository',
  operationId: 'repoGetAllCommits',
  request: {
    params: z.object({
      owner: z
        .string()
        .openapi({
          param: {
            description: 'owner of the repo',
            in: 'path',
            name: 'owner',
            required: true,
            schema: { type: 'string' },
          },
        }),
      repo: z
        .string()
        .openapi({
          param: {
            description: 'name of the repo',
            in: 'path',
            name: 'repo',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      sha: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: "SHA or branch to start listing commits from (usually 'master')",
            in: 'query',
            name: 'sha',
            schema: { type: 'string' },
            required: false,
          },
        }),
      path: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'filepath of a file/dir',
            in: 'query',
            name: 'path',
            schema: { type: 'string' },
            required: false,
          },
        }),
      since: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            description: 'Only commits after this date will be returned (ISO 8601 format)',
            in: 'query',
            name: 'since',
            schema: { format: 'date-time', type: 'string' },
            required: false,
          },
        }),
      until: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            description: 'Only commits before this date will be returned (ISO 8601 format)',
            in: 'query',
            name: 'until',
            schema: { format: 'date-time', type: 'string' },
            required: false,
          },
        }),
      stat: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description:
              "include diff stats for every commit (disable for speedup, default 'true')",
            in: 'query',
            name: 'stat',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
      verification: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description:
              "include verification for every commit (disable for speedup, default 'true')",
            in: 'query',
            name: 'verification',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
      files: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description:
              "include a list of affected files for every commit (disable for speedup, default 'true')",
            in: 'query',
            name: 'files',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'page number of results to return (1-based)',
            in: 'query',
            name: 'page',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description: "page size of results (ignored if used with 'path')",
            in: 'query',
            name: 'limit',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      not: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'commits that match the given specifier will not be listed.',
            in: 'query',
            name: 'not',
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: { 200: CommitListResponse, default: ErrorResponse },
})

