export const getReposOwnerRepoProjectsIdRoute = createRoute({
  method: 'get',
  path: '/repos/{owner}/{repo}/projects/{id}',
  tags: ['repository'],
  summary: 'Get a project',
  operationId: 'repoGetProject',
  request: {
    params: z.object({
      owner: z
        .string()
        .openapi({
          param: {
            description: 'owner of the repo',
            in: 'path',
            name: 'owner',
            required: true,
            schema: { type: 'string' },
          },
        }),
      repo: z
        .string()
        .openapi({
          param: {
            description: 'name of the repo',
            in: 'path',
            name: 'repo',
            required: true,
            schema: { type: 'string' },
          },
        }),
      id: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            description: 'id of the project',
            in: 'path',
            name: 'id',
            required: true,
            schema: { format: 'int64', type: 'integer' },
          },
        }),
    }),
  },
  responses: { 200: ProjectResponse, default: ErrorResponse },
})

